CREATE TABLE categories (id BIGSERIAL PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, description TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE customers (id BIGSERIAL PRIMARY KEY, customer_number VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, company VARCHAR(160), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE addresses (id BIGSERIAL PRIMARY KEY, customer_id BIGINT NOT NULL REFERENCES customers(id), type VARCHAR(20) NOT NULL, line1 VARCHAR(180) NOT NULL, city VARCHAR(80) NOT NULL, state VARCHAR(80), postal_code VARCHAR(30), country VARCHAR(2) NOT NULL DEFAULT 'US');
CREATE TABLE products (id BIGSERIAL PRIMARY KEY, sku VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, description TEXT, category_id BIGINT NOT NULL REFERENCES categories(id), price NUMERIC(12,2) NOT NULL CHECK(price>=0), active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inventory (id BIGSERIAL PRIMARY KEY, product_id BIGINT NOT NULL UNIQUE REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>=0), reorder_level INTEGER NOT NULL DEFAULT 10 CHECK(reorder_level>=0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE discounts (id BIGSERIAL PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, percentage NUMERIC(5,2) CHECK(percentage BETWEEN 0 AND 100), active BOOLEAN NOT NULL DEFAULT true, expires_at TIMESTAMPTZ);
CREATE TABLE orders (id BIGSERIAL PRIMARY KEY, order_number VARCHAR(40) NOT NULL UNIQUE, customer_id BIGINT NOT NULL REFERENCES customers(id), status VARCHAR(40) NOT NULL, total_amount NUMERIC(12,2) NOT NULL CHECK(total_amount>=0), discount_amount NUMERIC(12,2) NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id BIGINT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>0), unit_price NUMERIC(12,2) NOT NULL, line_total NUMERIC(12,2) NOT NULL);
CREATE TABLE payments (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id), status VARCHAR(40) NOT NULL, amount NUMERIC(12,2) NOT NULL, provider_reference VARCHAR(100), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE shipments (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id), status VARCHAR(40) NOT NULL, tracking_number VARCHAR(100), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_status_history (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, status VARCHAR(40) NOT NULL, message VARCHAR(300), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE application_events (id BIGSERIAL PRIMARY KEY, event_type VARCHAR(80) NOT NULL, message VARCHAR(500) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_products_name ON products(name); CREATE INDEX idx_customers_email ON customers(email); CREATE INDEX idx_orders_customer_created ON orders(customer_id,created_at DESC); CREATE INDEX idx_orders_status ON orders(status); CREATE INDEX idx_order_items_order ON order_items(order_id); CREATE INDEX idx_events_created ON application_events(created_at DESC);
